/**
 * Per-slug local images under `public/software-images/{slug}/`.
 * Generated by `scripts/download-software-images-unsplash.mjs`.
 */

import { linkForSoftwareRelated } from '../megaMenu'
import manifestJson from './softwareImageManifest.json'

export type PremiumPhotoPaths = {
  heroTeam: string
  financialReports: string
  dashboard: string
  teamMeeting: string
  ledgerOffice: string
}

export const PREMIUM_IMAGE_FALLBACK = '/accounts/hero-finance-team.jpg'

const MANIFEST = manifestJson as Record<string, PremiumPhotoPaths>

const SLUG_ALIASES: Record<string, string> = {
  'point-of-sale-software': 'point-of-sale-management-software',
  'sms-integration-system': 'integration-system',
  'oil-and-gas-business-management-software': 'fuel-tank-lorry-management-software',
  'petrol-gas-filling-station-software': 'petrol-gas-filling-station-software',
}

const LEGACY_PACK: PremiumPhotoPaths = {
  heroTeam: '/accounts/hero-finance-team.jpg',
  financialReports: '/accounts/financial-reports.jpg',
  dashboard: '/accounts/accounting-dashboard.jpg',
  teamMeeting: '/accounts/finance-team-meeting.jpg',
  ledgerOffice: '/accounts/ledger-documents.jpg',
}

export function getPremiumPhotoPaths(slug: string): PremiumPhotoPaths {
  const resolved = SLUG_ALIASES[slug] ?? slug
  return MANIFEST[resolved] ?? LEGACY_PACK
}

