export function relatedToIndustryLinks(
  related: { kind: 'module' | 'industry'; slug: string; label: string }[],
): { label: string; to: string }[] {
  return related.slice(0, 10).map((r) => ({
    label: r.label,
    to: linkForSoftwareRelated(r),
  }))
}
